import {mapEscape as e} from './maps-renderer.js?v=c4fa0c7979f6';
import {MAP_MODES,LAYERS,TOOL_LABELS,STATE_LABELS,SITUATIONS} from './maps-model.js?v=d29d1c20e4a9';
export const button=(action,label,{value='',primary=false,disabled=false,pressed}={})=>`<button type="button" class="btn${primary?' primary':''}" data-map-action="${action}"${value?` data-value="${e(value)}"`:''}${disabled?' disabled':''}${pressed===undefined?'':` aria-pressed="${pressed}"`}>${label}</button>`;
export const timelineStepLabel=(step,index)=>`<span>${index+1}</span>${e(step.title||'이름 없는 단계')}`;
export const options=(values,current)=>Object.entries(values).map(([key,label])=>`<option value="${e(key)}"${current===key?' selected':''}>${e(label)}</option>`).join('');
const select=(name,label,values,value)=>`<label>${label}<select data-map-field="${name}">${options(values,value)}</select></label>`;
export function mapHeader(catalog,map,{mode,readonly=false}={}){return `<header class="maps-heading"><div><p class="eyebrow">MANOR ATLAS</p><h1>맵 <span class="beta-badge">BETA</span></h1><p>지형을 살펴보고, 나만의 전술을 그려 보세요.</p></div>${button('help','베타 이용 안내')}</header><div class="maps-notice" role="note"><strong>실제 경기 배치를 확인해 주세요.</strong><span>공개 미니맵 기반의 베타입니다. 현재 게임 버전과 다를 수 있으며, 표식·경로는 전략 메모용입니다.</span></div>${readonly?'':`<div class="maps-picker" role="group" aria-label="지도 선택">${catalog.map(m=>`<button type="button" data-map-action="map" data-value="${m.id}" aria-pressed="${map.id===m.id}"><span class="maps-map-number">0${catalog.indexOf(m)+1}</span><strong>${e(m.name)}</strong><small>${m.floors.length}개 층</small></button>`).join('')}</div><div class="maps-modebar"><div class="segmented" role="group" aria-label="맵 모드">${Object.entries(MAP_MODES).map(([k,v])=>button('mode',v,{value:k,pressed:mode===k})).join('')}</div><div class="maps-actions">${button('library','내 전술')}${button('import','파일 가져오기')}</div></div>`}`;}
export function stageToolbar(map,floor,layers){return `<div class="maps-stage-toolbar"><div class="maps-floor" role="group" aria-label="지도 층">${map.floors.map(f=>button('floor',e(f.name),{value:f.id,pressed:floor===f.id})).join('')}</div><div class="maps-actions">${button('zoom-out','−')}${button('zoom-in','＋')}${button('reset-view','전체 보기')}</div></div><details class="maps-layers"><summary>레이어 <span>표시할 요소 선택</span></summary><div>${Object.entries(LAYERS).map(([id,name])=>`<label><input type="checkbox" data-map-layer="${id}"${layers.has(id)?' checked':''}>${name}</label>`).join('')}</div><p>지형 이미지는 원본 요소를 포함합니다. 자원 레이어는 직접 추가한 표식을 켜고 끕니다.</p></details>`;}
export function toolsHTML(tool){return `<div class="maps-tools" role="group" aria-label="전술 도구">${Object.entries(TOOL_LABELS).map(([id,label])=>button('tool',label,{value:id,pressed:tool===id})).join('')}</div><p class="maps-hint">도구를 고르고 지도를 누르세요. 경로는 지점을 차례로 찍은 뒤 완료하세요. 두 손가락으로 확대할 수 있습니다.</p><div class="maps-drawing" hidden>${button('finish-path','경로 완료',{primary:true})}${button('cancel-path','취소')}<span data-map-draft-count></span></div>`;}
export function conditionsHTML(plan,characters){const c=plan.conditions,roster=Object.values(characters).filter(v=>v.side===(c.faction==='survivor'?'생존자':'감시자'));return `<details class="maps-conditions"><summary>적용 조건 <span>${c.faction==='survivor'?'생존자':'감시자'} · ${SITUATIONS[c.situation]}</span></summary><div class="maps-field-grid">${select('condition.server','서버',{global:'글로벌',cn:'중국'},c.server)}${select('condition.mode','경기 모드',{standard:'일반 1 대 4',practice:'연습'},c.mode)}${select('condition.layout','배치 기준',{reference:'참조 지형',assumed:'사용자 가정'},c.layout)}${select('condition.faction','진영',{survivor:'생존자',hunter:'감시자'},c.faction)}${select('condition.characterId','캐릭터',{'':'공통',...Object.fromEntries(roster.map(v=>[v.id,v.name]))},c.characterId)}${select('condition.situation','상황',SITUATIONS,c.situation)}</div><label>시작 조건·게임 버전 메모<textarea data-map-field="condition.note" maxlength="500" rows="3" placeholder="상대 위치, 기술 상태, 직접 확인한 게임 버전 등을 기록하세요.">${e(c.note)}</textarea></label><p class="maps-hint">조건을 바꾸면 기존 경로를 재확인 상태로 표시합니다.</p></details>`;}
export function inspectorHTML(plan,step,selected,characters){const item=plan.steps[step]?.items.find(i=>i.id===selected);if(!item)return `<section class="maps-inspector"><h3>표식 편집</h3><p class="maps-hint">지도 위 표식을 선택해 이동하거나 내용을 바꾸세요.</p><p class="maps-hint">현재 단계 ${plan.steps[step].items.length}/60개 · 표식은 모두 사용자 가정입니다.</p></section>`;return `<section class="maps-inspector"><div class="maps-row"><h3>${TOOL_LABELS[item.kind]}</h3>${button('delete-item','삭제')}</div><label>이름·메모<input data-map-field="item.label" maxlength="160" value="${e(item.label)}"></label><div class="maps-field-grid">${select('item.color','색상',{green:'초록',red:'빨강',blue:'파랑',gold:'금색',purple:'보라'},item.color)}${select('item.state','자원·캐릭터 상태',STATE_LABELS,item.state)}${item.kind==='character'?select('item.characterId','캐릭터',{'':'이름 없는 표식',...Object.fromEntries(Object.values(characters).map(c=>[c.id,c.name]))},item.characterId):''}${item.kind==='area'?`<label>범위<input type="range" min="12" max="180" data-map-field="item.radius" value="${item.radius}"></label>`:''}</div>${item.needsReview?`<p class="maps-warning">실제 경기 조건과 경로를 직접 확인해 주세요.</p>${button('review-item','직접 확인 완료')}`:''}<p class="maps-hint">드래그 또는 표식에 초점을 둔 뒤 방향키로 이동합니다. Shift를 누르면 더 크게 이동합니다.</p></section>`;}
export function timelineHTML(plan,step,{readonly=false,playing=false}={}){return `<div class="maps-timeline"><div class="maps-row"><h3>전술 단계</h3>${button('play',playing?'일시정지':'단계 재생',{disabled:plan.steps.length<2})}</div><div class="maps-step-list" role="group" aria-label="전술 단계">${plan.steps.map((s,i)=>button('step',timelineStepLabel(s,i),{value:String(i),pressed:i===step})).join('')}</div>${readonly?'':`<div class="maps-actions">${button('add-step','단계 추가',{disabled:plan.steps.length>=16})}${button('copy-step','복제',{disabled:plan.steps.length>=16})}${button('step-up','앞으로',{disabled:step===0})}${button('step-down','뒤로',{disabled:step===plan.steps.length-1})}${button('remove-step','단계 삭제',{disabled:plan.steps.length<2})}</div><div class="maps-field-grid"><label>단계 이름<input data-map-field="step.title" value="${e(plan.steps[step].title)}" maxlength="60"></label><label>표시 간격 · 초<input type="number" min="1" max="15" step="1" data-map-field="step.duration" value="${plan.steps[step].duration}"></label></div><label>단계 설명<textarea rows="3" maxlength="600" data-map-field="step.note">${e(plan.steps[step].note)}</textarea></label>`}${readonly?`<p class="maps-step-note">${e(plan.steps[step].note)}</p>`:''}<p class="maps-hint">재생은 설명 순서를 보여 줍니다. 실제 이동 시간이나 게임 판정을 계산하지 않습니다.</p></div>`;}
export function explorePanel(map,query=''){const results=map.landmarks.filter(l=>l.name.includes(query));return `<section><p class="maps-kicker">EXPLORE</p><h2>${e(map.name)}</h2><p class="maps-hint">${e(map.intro)}</p><label class="maps-search">구역 찾기<input type="search" data-map-search value="${e(query)}" placeholder="건물·구역 이름" maxlength="40"></label><div class="maps-regions">${results.map(l=>button('landmark',e(l.name),{value:l.id})).join('')||'<p>일치하는 구역이 없습니다.</p>'}</div><p class="maps-hint">구역 이름과 위치는 참조 자료를 옮긴 근사값입니다. 인게임 통칭과 다를 수 있습니다.</p>${button('mode','이 지도에서 전술 만들기',{value:'tactics',primary:true})}</section>`;}
export function guidePanel(map,{faction,situation,characterId,characters,guide,guideStep=0}){const guides=map.guides.filter(g=>(!faction||g.faction===faction)&&(!situation||g.situation===situation)&&(!g.characterIds.length||g.characterIds.includes(characterId)));return `<section><p class="maps-kicker">CONDITIONAL GUIDES</p><h2>조건별 공략</h2><p class="maps-hint">초기 베타에는 검증 전 연습 예시를 제공합니다. 조건과 근거를 확인하고 자신의 전술로 보완하세요.</p><div class="maps-field-grid">${select('guide.faction','진영',{'':'전체',survivor:'생존자',hunter:'감시자'},faction)}${select('guide.situation','상황',{'':'전체',...SITUATIONS},situation)}${select('guide.characterId','캐릭터',{'':'공통',...Object.fromEntries(Object.values(characters).map(c=>[c.id,c.name]))},characterId)}</div><div class="maps-guide-list">${guides.map(g=>button('guide',`<strong>${e(g.title)}</strong><small>${g.faction==='survivor'?'생존자':'감시자'} · ${SITUATIONS[g.situation]}</small>`,{value:g.id,pressed:guide?.id===g.id})).join('')||'<p class="maps-hint">이 조건의 예시는 아직 없습니다. 직접 전술을 작성할 수 있습니다.</p>'}</div>${guide?`<article class="maps-guide-detail"><span class="maps-warning">${e(guide.status)}</span><h3>${e(guide.title)}</h3><dl><dt>시작 조건</dt><dd>${e(guide.start)}</dd><dt>현재 단계 · ${guideStep+1}</dt><dd>${e(guide.steps[guideStep].text)}</dd><dt>선택 이유</dt><dd>${e(guide.steps[guideStep].reason)}</dd><dt>전환 기준</dt><dd>${e(guide.steps[guideStep].switch)}</dd><dt>대안</dt><dd>${e(guide.steps[guideStep].alternative)}</dd></dl>${button('use-guide','내 전술로 가져오기',{primary:true})}<details><summary>근거·검토 상태</summary><p>${e(guide.evidence)}</p><p>작성 검토 ${guide.reviewedAt} · 실전 검증 전</p></details></article>`:''}</section>`;}
export function sourceHTML(map){return `<details class="maps-sources"><summary>지도 출처·버전·표식 기준</summary><dl><dt>참조 판본</dt><dd>${e(map.revision)} · 원본 페이지 갱신 ${e(map.source.pageUpdated)}</dd><dt>자료 확인</dt><dd>${map.source.checkedAt} · 이미지 촬영 버전과 현재 클라이언트 일치 여부는 미검증입니다.</dd><dt>좌표·배치</dt><dd>지형과 구역 표시는 참조 자료입니다. 해독기·의자·시작 위치·판자 상태는 자동 확정하지 않습니다. 계단 그림만으로 활성 지하실을 판단할 수 없습니다.</dd><dt>권리·출처</dt><dd>지도 이미지: Identity V / NetEase · <a href="${e(map.source.url)}" target="_blank" rel="noopener noreferrer">BWIKI 제5인격 위키 ↗</a></dd></dl></details>`;}
